(function(root){
'use strict';
function mount(panel,options={}){
 const model=root.PLReconstructedModel.create(root.PLReconstructedSample,root.PLOfficialSample),esc=root.MatchWorkspace.esc,node=id=>panel.querySelector('#pl-r-'+id),text=(n,s)=>{if(n.textContent!==s)n.textContent=s;};
 let cursor=0,selected=model.slots[0].id,speed=1,active=false,raf=null,generation=0,rosterKey='',factKey='',selectedHighlight=null,highlightEnd=null,highlightFilter='goal',highlightsKey='';
 const now=()=>root.performance?.now?.()??Date.now(),questions=['Where is this player?','Where is the ball?','What has been reported?','What is the score?','What supports this?'];
 panel.innerHTML=`<div class="goal-context"><div><span class="eyebrow">GENERATED RECONSTRUCTION</span><h2>Reconstructed replay</h2><p>Brentford–Chelsea · Whole match · Real roster, illustrated movement</p></div><details class="goal-sources"><summary>Sources & method ↗</summary><p>Official match lineups, formation labels and fourteen reported goals, substitutions and cards provide the anchors. Runs, passes, position slots and all movement between anchors are deterministic authored illustration, not recovered tracking or verified tactical roles.</p><p>Reported minutes retain unknown seconds. To keep the animation, roster and source answers aligned, events are staged at the end of their reported minute window. Same-minute changes are simultaneous here, without asserting their actual order. The score counts only reported goals whose minute windows have elapsed. No actual pass, possession, speed or distance statistic is generated.</p><p>Both halves play, with authored +2 / +6 added-time lengths and an explicit half-time change of ends. These are illustrative bounds, not verified whistles. This clock is independent of source-video time. The Evidence view preserves reviewed positions, cameras and gaps separately.</p><p><a href="${esc(model.source.url)}" target="_blank" rel="noopener">Official Premier League match record ↗</a></p><details><summary>Illustration receipt</summary><pre tabindex="0">${esc(JSON.stringify(root.PLReconstructedReceipt,null,2))}</pre></details></details></div>
 <div class="reconstructed-evidence"><strong>Generated reconstruction</strong><span>Smooth illustration around documented events</span><button data-r-evidence="passage">Evidence view · reviewed footage →</button><button data-r-evidence="official">Official match record →</button></div>
 <section class="reconstructed-highlights" aria-labelledby="pl-r-highlights-title"><div class="reconstructed-highlights-heading"><div><span class="eyebrow">THE MATCH, IN MOMENTS</span><h3 id="pl-r-highlights-title">Match highlights</h3></div><p id="pl-r-index-note">Full-match index · Retrospective spoilers</p></div><div class="reconstructed-highlight-filters" role="group" aria-label="Filter match highlights"><button data-r-filter="goal" id="pl-r-filter-goal" aria-pressed="true">Goals <span>3</span></button><button data-r-filter="substitution" id="pl-r-filter-substitution" aria-pressed="false">Substitutions <span>9</span></button><button data-r-filter="yellow_card" id="pl-r-filter-yellow_card" aria-pressed="false">Cards <span>2</span></button></div><div id="pl-r-highlight-cards" class="reconstructed-highlight-cards"></div></section>
 <div class="goal-layout"><section class="goal-pitch-panel reconstructed-pitch-panel" aria-label="Generated whole-match pitch replay"><div class="goal-pitch-meta"><strong id="pl-r-period">First half</strong><span id="pl-r-clock"></span><strong id="pl-r-score"></strong></div><div class="goal-pitch reconstructed-pitch" id="pl-r-field" role="group" aria-label="Generated football illustration. Home team red, away team blue. Select a named player or use the roster."><svg viewBox="0 0 105 68" preserveAspectRatio="none" aria-hidden="true"><path d="M0 0H105V68H0Z M52.5 0V68 M0 13.84H16.5V54.16H0 M105 13.84H88.5V54.16H105 M0 24.84H5.5V43.16H0 M105 24.84H99.5V43.16H105 M16.5 26.69A9.15 9.15 0 0 1 16.5 41.31 M88.5 26.69A9.15 9.15 0 0 0 88.5 41.31"/><circle cx="52.5" cy="34" r="9.15"/></svg>${model.slots.map(s=>`<button id="pl-r-marker-${s.id}" class="reconstructed-marker ${s.team}" data-r-slot="${s.id}" aria-pressed="false"><span id="pl-r-shirt-${s.id}"></span></button>`).join('')}<span id="pl-r-ball" class="reconstructed-ball" role="img" aria-label="Generated ball position"></span><p id="pl-r-halftime" class="reconstructed-halftime" hidden>Half-time<br><small>Illustrated change of ends · Play to continue</small></p></div><div class="reconstructed-caption"><span id="pl-r-phase"></span><span id="pl-r-selected"></span></div><div id="pl-r-highlight-context" class="reconstructed-highlight-context" hidden><div><small>Selected from the full-match index</small><strong id="pl-r-highlight-title"></strong><span id="pl-r-highlight-minute"></span></div><button id="pl-r-ask-moment">Ask about this moment ↗</button></div><div class="goal-transport"><label for="pl-r-range">Illustrated match clock <strong id="pl-r-time"></strong></label><input id="pl-r-range" type="range" min="0" max="${model.duration}" step="0.1" value="0"><div class="reconstructed-goal-timeline" role="group" aria-label="Watch a goal on the illustrated timeline" aria-describedby="pl-r-index-note"><div class="reconstructed-goal-track">${model.goalIndex.map(g=>`<button id="pl-r-goal-pin-${g.id}" class="reconstructed-goal-pin" data-r-highlight="${g.id}" style="left:${g.stage/model.duration*100}%" aria-pressed="false" aria-label="Watch goal ${g.number}, ${esc(g.scorer)}, reported ${esc(g.reportedMinute)} minutes"><span>${g.number}</span><small>${esc(g.reportedMinute)}′</small></button>`).join('')}</div></div><div class="reconstructed-half-labels"><span>First half +2</span><span>Second half +6 · illustrative added time</span></div><div class="goal-controls"><button id="pl-r-play" aria-pressed="false">▶ Play</button><button id="pl-r-start">← Start</button><button id="pl-r-previous">−15 s</button><button id="pl-r-next">+15 s</button><button id="pl-r-half">Second half →</button><button id="pl-r-end">End →</button><label class="reconstructed-speed" for="pl-r-speed">Speed <select id="pl-r-speed"><option value="1">1×</option><option value="4">4×</option><option value="12">12× overview</option></select></label></div><p id="pl-r-status" class="goal-readout" role="status" aria-live="polite">Paused · Choose a player or press Play.</p></div><section class="reconstructed-events" aria-label="Eligible source-reported moments"><h3>Reported by this clock</h3><p id="pl-r-event-empty">No selected reported-event minute has fully elapsed yet.</p><ol id="pl-r-events"></ol></section></section>
 <aside class="goal-roster reconstructed-roster" aria-label="Illustrated lineup"><div class="goal-roster-heading"><h3>On the pitch</h3><span>22 stable illustrated slots</span></div><p class="reconstructed-roster-note">Source names & shirts · Position assignments are generated</p><table><thead><tr><th scope="col">Player</th><th scope="col">Illustrated slot</th></tr></thead><tbody>${model.slots.map(s=>`<tr id="pl-r-row-${s.id}" class="${s.team}"><th scope="row"><button data-r-slot="${s.id}" aria-pressed="false"><span id="pl-r-row-shirt-${s.id}" class="reconstructed-shirt ${s.team}"></span><span id="pl-r-name-${s.id}"></span></button></th><td>${esc(s.label)}</td></tr>`).join('')}</tbody></table><details class="reconstructed-bench"><summary>Starting bench & reported changes</summary><p>Starting bench from the official lineup:</p>${['brentford','chelsea'].map(team=>`<p><strong>${team==='brentford'?'Brentford':'Chelsea'}</strong>: ${model.people.filter(p=>p.team===team&&p.status==='bench').map(p=>esc(p.name)).join(', ')}</p>`).join('')}<ul id="pl-r-changes"></ul><p>Illustrated substitutions inherit the outgoing slot at the reported-minute endpoint. This does not establish their exact real time or actual tactical role.</p></details></aside></div>
 <section class="conversation reconstructed-conversation" aria-label="Questions about this generated replay"><div class="conversation-bar"><div><span class="avatar" aria-hidden="true">↗</span><div><strong>At this moment</strong><small>Generated illustration + eligible source reports</small></div></div></div><div id="pl-r-thread" role="log" aria-live="polite" aria-label="Current-clock answers"></div><div id="pl-r-questions" class="reconstructed-questions">${questions.map(q=>`<button data-r-question="${esc(q)}">${esc(q)}</button>`).join('')}</div><form id="pl-r-composer"><label for="pl-r-draft" class="sr-only">Question about this illustrated moment</label><input id="pl-r-draft" autocomplete="off" placeholder="Ask about this player or moment…"><button type="submit" aria-label="Send question">↑</button></form><p id="pl-r-answer-status" class="goal-readout">Answers distinguish generated movement from source-reported facts.</p></section>`;
 function paintHighlights(){
  const h=model.highlight(selectedHighlight),key=highlightFilter+'|'+selectedHighlight;
  if(key!==highlightsKey){highlightsKey=key;node('highlight-cards').innerHTML=model.highlightIndex.filter(h=>h.kind===highlightFilter).map(h=>`<article class="reconstructed-highlight-card ${h.kind==='goal'?'is-goal':'is-compact'} ${h.id===selectedHighlight?'selected':''}"><div class="reconstructed-highlight-top"><span>${h.kind==='goal'?'GOAL '+h.number:h.kind==='substitution'?'SUBSTITUTION':'YELLOW CARD'} · ${esc(h.reportedMinute)}′</span>${h.kind==='goal'?`<strong>${h.scoreAfter.join('–')}<small>after goal</small></strong>`:''}</div><h4>${esc(h.scorer||h.actor)}</h4><p>${h.kind==='goal'?(h.assist?'Assist · '+esc(h.assist):'Brentford'):h.kind==='substitution'?'For '+esc(h.off):esc(h.reason||'Reported booking')}</p><button data-r-highlight="${h.id}" aria-pressed="${h.id===selectedHighlight}">${h.kind==='goal'?'▶ ':''}${esc(h.cta)}${h.kind==='goal'?'':' →'}</button></article>`).join('');
   for(const kind of ['goal','substitution','yellow_card'])node('filter-'+kind).setAttribute('aria-pressed',String(kind===highlightFilter));
   for(const g of model.goalIndex)node('goal-pin-'+g.id).setAttribute('aria-pressed',String(g.id===selectedHighlight));
   node('highlight-context').hidden=!h;if(h){text(node('highlight-title'),h.kind==='goal'?h.scorer+' · '+h.scoreAfter.join('–'):h.kind==='substitution'?h.actor+' for '+h.off:h.actor+' · Yellow card');text(node('highlight-minute'),'Reported '+h.reportedMinute+'′ · '+(h.kind==='goal'?'Generated goal replay':'Reported moment'));}
  }
 }
 function clear(){node('thread').replaceChildren();text(node('answer-status'),'Answers use this illustrated clock and selected player.');}
 function stop(){const playing=raf!==null;generation++;if(raf!==null)root.cancelAnimationFrame(raf);raf=null;text(node('play'),'▶ Play');node('play').setAttribute('aria-pressed','false');if(playing)text(node('status'),'Paused at '+model.clock(cursor)+'.');}
 function paint(){paintHighlights();const f=model.frame(cursor,selected);for(const p of f.players){const m=node('marker-'+p.slotId);m.style.left=(p.x/105*100)+'%';m.style.top=(p.y/68*100)+'%';m.setAttribute('aria-pressed',String(p.slotId===selected));}node('ball').style.left=(f.ball.x/105*100)+'%';node('ball').style.top=(f.ball.y/68*100)+'%';
  const key=f.players.map(p=>p.player.id).join('|')+'|'+selected;if(key!==rosterKey){rosterKey=key;for(const p of f.players){const id=p.slotId,label=p.player.name+' · '+(p.team==='brentford'?'Brentford':'Chelsea')+' '+p.player.shirt;text(node('shirt-'+id),String(p.player.shirt));text(node('row-shirt-'+id),String(p.player.shirt));text(node('name-'+id),p.player.name);node('marker-'+id).setAttribute('aria-label',label+'. Generated '+p.slotLabel.toLowerCase()+'.');const row=node('row-'+id);row.classList.toggle('selected',id===selected);row.querySelector('button').setAttribute('aria-pressed',String(id===selected));}}
  text(node('clock'),f.clock);text(node('time'),f.clock);text(node('period'),f.period===1?'First half':'Second half');text(node('score'),'Reported goals · '+f.score.join('–'));text(node('phase'),f.ball.phase);text(node('selected'),f.selected.player.name+' · '+f.selected.slotLabel);node('range').value=String(cursor);node('range').setAttribute('aria-valuetext',(f.period===1?'First':'Second')+' half '+f.clock+'. Generated reconstruction. Reported goals '+f.score.join('–')+'.');node('halftime').hidden=cursor!==model.half;node('previous').disabled=cursor===0;node('next').disabled=cursor===model.duration;node('play').disabled=cursor===model.duration;
  const facts=f.facts.map(e=>e.id).join('|');if(facts!==factKey){factKey=facts;node('events').innerHTML=f.facts.map(e=>`<li><strong>${esc(e.time.printed)}′</strong><span>${esc(model.eventText(e))}</span><small>Reported minute · exact second unknown</small></li>`).join('');node('changes').innerHTML=f.facts.filter(e=>e.kind==='substitution').map(e=>`<li>${esc(e.time.printed)}′ ${esc(model.eventText(e))}</li>`).join('');}node('event-empty').hidden=f.facts.length>0;
 }
 function seek(t){stop();highlightEnd=null;cursor=Math.max(0,Math.min(model.duration,Number.isFinite(t)?t:0));clear();paint();text(node('status'),cursor===model.half?'Half-time · Illustrated change of ends. Play to continue.':cursor===model.duration?'End of the illustration · added time and endpoint are authored.':'Paused at '+model.clock(cursor)+'.');}
 function run(limit=null){if(!active||cursor===model.duration)return;stop();highlightEnd=limit;clear();const token=generation,origin=cursor,started=now(),end=highlightEnd??model.duration,watching=highlightEnd!==null;const tick=()=>{if(!active||token!==generation)return;let next=Math.min(end,origin+(now()-started)/1000*speed);if(origin<model.half&&next>=model.half){cursor=model.half;paint();stop();highlightEnd=null;text(node('status'),'Half-time · Illustrated change of ends. Play to continue.');return;}cursor=next;paint();if(cursor===end){stop();highlightEnd=null;text(node('status'),watching?'Highlight complete at '+model.clock(cursor)+' · Play to continue the match.':'End of the illustration · added time and endpoint are authored.');return;}raf=root.requestAnimationFrame(tick);};raf=root.requestAnimationFrame(tick);text(node('play'),'Ⅱ Pause');node('play').setAttribute('aria-pressed','true');text(node('status'),watching?'Watching goal highlight at 1×.':'Playing generated reconstruction at '+speed+'×.');}
 function openHighlight(id){const h=model.highlight(id);if(!h)return;stop();highlightEnd=null;selectedHighlight=id;highlightFilter=h.kind;selected=h.slotId;cursor=h.kind==='goal'?h.leadIn:h.stage;clear();if(h.kind==='goal'){speed=1;node('speed').value='1';}paint();if(h.kind==='goal')run(h.watchEnd);else text(node('status'),'Reported '+h.reportedMinute+'′ · Paused at '+model.clock(cursor)+'.');const field=node('field'),play=node('play'),bounds=field.getBoundingClientRect?.();if(bounds&&(bounds.top<0||bounds.bottom>root.innerHeight))field.scrollIntoView?.({behavior:'auto',block:'center'});play.focus({preventScroll:true});play.scrollIntoView?.({behavior:'auto',block:'nearest',inline:'nearest'});}

 function select(id){if(!model.slots.some(s=>s.id===id))return;stop();highlightEnd=null;selected=id;clear();paint();text(node('status'),model.frame(cursor,selected).selected.player.name+' selected.');}
 function ask(q){if(!String(q).trim())return;stop();highlightEnd=null;const f=model.frame(cursor,selected),a=model.answer(cursor,selected,q),stamp=f.clock+' · '+f.selected.player.name;node('thread').insertAdjacentHTML('beforeend',root.MatchWorkspace.message(q,true,stamp,'')+root.MatchWorkspace.message(a.text,false,stamp,'Generated reconstruction · '+(a.kind==='source'?'eligible source reports':'illustrated movement')));text(node('answer-status'),'Answer at '+f.clock+' · generated reconstruction.');}
 node('range').addEventListener('input',e=>seek(Number(e.target.value)));node('speed').addEventListener('change',e=>{const resume=raf!==null;stop();speed=[1,4,12].includes(Number(e.target.value))?Number(e.target.value):1;if(resume)run();});node('composer').addEventListener('submit',e=>{e.preventDefault();ask(node('draft').value);node('draft').value='';});
 panel.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.rSlot)select(b.dataset.rSlot);else if(b.dataset.rQuestion)ask(b.dataset.rQuestion);else if(b.dataset.rHighlight)openHighlight(b.dataset.rHighlight);else if(b.dataset.rFilter&&['goal','substitution','yellow_card'].includes(b.dataset.rFilter)){highlightFilter=b.dataset.rFilter;paintHighlights();}else if(b.dataset.rEvidence){stop();highlightEnd=null;clear();options.onEvidence?.(b.dataset.rEvidence);}else if(b.id==='pl-r-play'){if(raf!==null){stop();highlightEnd=null;}else run();}else if(b.id==='pl-r-start')seek(0);else if(b.id==='pl-r-end')seek(model.duration);else if(b.id==='pl-r-half')seek(model.half);else if(b.id==='pl-r-previous')seek(cursor-15);else if(b.id==='pl-r-next')seek(cursor+15);else if(b.id==='pl-r-ask-moment')ask('What has been reported?');});
 paint();return {activate(){active=true;stop();highlightEnd=null;clear();paint();},deactivate(){active=false;stop();highlightEnd=null;clear();},stop(){stop();highlightEnd=null;clear();}};
}
root.PLReconstructedView={mount};
})(window);
